    private static DocumentBlock Node(string id,string title,string name,Formula f,AssessedProvenance provenance,string prose,DescribeRole role) =>
        Describe.Lean(DescribeId.Create("twinfreethetastructure-"+id),DeclarationHandle.Create(Prefix+name),H(title),
            StatementSource.FromAuthor(Disp(f)),provenance,Blocks(Paragraph(Text(prose))),role);
    private static Formula V(string s) => F.Id(s);
    private static Formula C(string s) => Seq(Operatorname, Grp(V(s)));
    private static Formula Q(string owner,string name) => Seq(C(owner), Dot, C(name));
    private static Formula Qualified3(string a,string b,string c) => Seq(C(a),Dot,C(b),Dot,C(c));
    private static Formula DotName(Formula a,string name) => Seq(Parenthesized(a),Dot,C(name));
    private static Formula App(Formula f,params Formula[] a) => new Formula.Apply(f,[..a]);
    private static Formula Call(string s,params Formula[] a) => a.Length == 0 ? C(s) : App(C(s),a);
    private static Formula All(string s,Formula t,Formula b) => Seq(Forall,Sp,V(s),Colon,Sp,t,Comma,Sp,b);
    private static Formula Some(string s,Formula t,Formula b) => Seq(Exists,Sp,V(s),Colon,Sp,t,Comma,Sp,b);
    private static Formula Eqn(Formula a,Formula b) => new Formula.Relation(a,FormulaRelationOperator.Equal,b);
    private static Formula Ne(Formula a,Formula b) => new Formula.Relation(a,FormulaRelationOperator.NotEqual,b);
    private static Formula Le(Formula a,Formula b) => new Formula.Relation(a,FormulaRelationOperator.LessThanOrEqual,b);
    private static Formula And(Formula a,Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.And,Parenthesized(b));
    private static Formula Or(Formula a,Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.Or,Parenthesized(b));
    private static Formula Implies(Formula a,Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.Implies,Parenthesized(b));
    private static Formula NotOf(Formula a) => new Formula.Not(Parenthesized(a));
    private static Formula IffOf(Formula a,Formula b) => new Formula.Logic(Parenthesized(a),FormulaLogicOperator.Iff,Parenthesized(b));
    private static Formula Add(Formula a,Formula b) => new Formula.Binary(a,FormulaBinaryOperator.Add,b);
    private static Formula Mul(Formula a,Formula b) => new Formula.Binary(a,FormulaBinaryOperator.Multiply,b);
    private static Formula TypedLam(Formula v,Formula t,Formula b) => Seq(LambdaLower,Sp,Parenthesized(Seq(v,Colon,Sp,t)),Sp,Mapsto,Sp,b);
    private static Formula SetOf(Formula v,Formula t,Formula p) => Seq(OpenBrace,Sp,v,Colon,Sp,t,Sp,Mid,Sp,p,Sp,CloseBrace);
    private static Formula SetDifference(Formula a,Formula b) => Seq(a,Sp,Setminus,Sp,b);
    private static Formula Parenthesized(Formula f) => Seq(Open,f,Close);
